def is_right_triangle(p1, p2, p3):
    def d2(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2
    sides = sorted([d2(p1, p2), d2(p2, p3), d2(p3, p1)])
    return sides[0] + sides[1] == sides[2]

def rectangle_perimeter(rect):
    x1, y1, x2, y2 = rect
    return 2 * ((x2 - x1) + (y2 - y1))

def rectangle_area(rect):
    x1, y1, x2, y2 = rect
    return (x2 - x1) * (y2 - y1)

def total_manhattan_path_length(points):
    if len(points) < 2:
        return 0
    total = 0
    for i in range(len(points) - 1):
        total += abs(points[i][0] - points[i + 1][0]) + abs(points[i][1] - points[i + 1][1])
    return total

def nearest_point(target, points):
    best = points[0]
    best_d2 = (target[0] - best[0]) ** 2 + (target[1] - best[1]) ** 2
    for p in points[1:]:
        d2 = (target[0] - p[0]) ** 2 + (target[1] - p[1]) ** 2
        if d2 < best_d2:
            best = p
            best_d2 = d2
    return best

def normalize_rectangle(p1, p2):
    x1 = min(p1[0], p2[0])
    x2 = max(p1[0], p2[0])
    y1 = min(p1[1], p2[1])
    y2 = max(p1[1], p2[1])
    return (x1, y1, x2, y2)

def polygon_centroid(points):
    n = len(points)
    cx = sum(p[0] for p in points) / n
    cy = sum(p[1] for p in points) / n
    return (cx, cy)

def rotate_90_clockwise(grid):
    if not grid or not grid[0]:
        return []
    return [list(row) for row in zip(*grid[::-1])]

def rotate_90_counterclockwise(grid):
    if not grid or not grid[0]:
        return []
    return [list(row) for row in list(zip(*grid))[::-1]]
